WITH lines AS (SELECT id, effective_from, currency, EXPLODE_OUTER(discounts) AS tier_value FROM price_tiers), with_windows AS (SELECT *, PERCENT_RANK() OVER (PARTITION BY currency ORDER BY tier_value DESC NULLS LAST) AS tier_value_percent_rank, CUME_DIST() OVER (PARTITION BY currency ORDER BY tier_value ASC NULLS LAST) AS tier_value_cume_dist FROM lines), valid AS (SELECT *, tier_value * tier_value_cume_dist AS tier_value_times_tier_value_cume_dist FROM with_windows WHERE effective_from > DATE '2024-07-27' AND effective_from < '2023-03-01'), metrics AS (SELECT *, DENSE_RANK() OVER (ORDER BY tier_value_times_tier_value_cume_dist ASC NULLS FIRST) AS tier_value_times_tier_value_cume_dist_dense_rank, PERCENT_RANK() OVER (ORDER BY tier_value_cume_dist DESC) AS tier_value_cume_dist_percent_rank FROM valid), filtered AS (SELECT *, ROUND(tier_value_percent_rank / tier_value_times_tier_value_cume_dist_dense_rank, 2) AS tier_value_percent_rank_per_tier_value_times_tier_value_cume_dist_dense_rank, ROUND(tier_value_times_tier_value_cume_dist_dense_rank * 1.15, 2) AS adjusted_tier_value_times_tier_value_cume_dist_dense_rank FROM metrics WHERE effective_from > DATE '2024-10-21'), remaining_keys AS (SELECT currency FROM filtered INTERSECT ALL SELECT currency FROM price_tiers WHERE currency IN ('THB', 'EUR', 'USD')), reconciled AS (SELECT s.* FROM filtered s JOIN remaining_keys k ON s.currency = k.currency), kept_keys AS (SELECT id FROM reconciled INTERSECT ALL SELECT id FROM price_tiers WHERE currency = 'THB'), verified AS (SELECT s.* FROM reconciled s JOIN kept_keys k ON s.id = k.id) SELECT CASE WHEN adjusted_tier_value_times_tier_value_cume_dist_dense_rank >= 83 THEN 'LARGE' ELSE 'SMALL' END AS adjusted_tier_value_times_tier_value_cume_dist_dense_rank_tier, SUM(tier_value_times_tier_value_cume_dist) AS total_tier_value_times_tier_value_cume_dist, PERCENTILE_APPROX(tier_value_times_tier_value_cume_dist_dense_rank, ARRAY(0.25, 0.5, 0.75)) AS tier_value_times_tier_value_cume_dist_dense_rank_quartiles, PERCENTILE_APPROX(tier_value_cume_dist_percent_rank, 0.5) AS tier_value_cume_dist_percent_rank_p50, COUNT_IF(currency = 'THB') AS thb_events, AVG(tier_value) AS avg_tier_value FROM verified GROUP BY adjusted_tier_value_times_tier_value_cume_dist_dense_rank_tier
